# 소프트웨어 아키텍처 결정 예시: Python 3에서 실행 가능한 코드
decision = {"choice": "event-driven", "reason": "loose coupling"}
print(decision["choice"])

# 품질 속성(Quality Attributes) 예시: Python 3에서 실행 가능한 코드
attributes = {"availability": 99.9, "latency_ms": 200}
print(attributes["availability"] > 99)

# 아키텍처 트레이드오프 예시: Python 3에서 실행 가능한 코드
choice = {"speed": 9, "cost": 6, "simplicity": 5}
print(max(choice, key=choice.get))

# 기술 선택 프레임워크 예시: Python 3에서 실행 가능한 코드
scores = {"fit": 5, "ops": 4, "risk": 2}
print(sum(scores.values()))

# 오픈소스 평가 기준 예시: Python 3에서 실행 가능한 코드
project = {"license": "Apache-2.0", "recent_release": True}
print(project["recent_release"])

# 기술 부채 상환 전략 예시: Python 3에서 실행 가능한 코드
debts = {"old_api": 8, "tests": 5}
print(max(debts, key=debts.get))

# 플랫폼 엔지니어링 예시: Python 3에서 실행 가능한 코드
platform = {"deploy": "self-service", "logs": "standard"}
print(platform["deploy"])

# 내부 개발자 플랫폼(IDP) 예시: Python 3에서 실행 가능한 코드
idp = {"create_service": True, "view_logs": True}
print(all(idp.values()))

# 서비스 카탈로그 예시: Python 3에서 실행 가능한 코드
catalog = {"payment": {"owner": "fintech-team"}}
print(catalog["payment"]["owner"])

# 스트림 정렬 팀 예시: Python 3에서 실행 가능한 코드
team = {"owns": "checkout", "runs_service": True}
print(team["owns"])

# 플랫폼 팀 예시: Python 3에서 실행 가능한 코드
platform_team = {"provides": ["ci", "runtime", "observability"]}
print(platform_team["provides"])

# 인에이블링 팀 예시: Python 3에서 실행 가능한 코드
skills = {"kubernetes": "coached"}
print(skills["kubernetes"])

# 복잡한 서브시스템 팀 예시: Python 3에서 실행 가능한 코드
subsystem = {"name": "ranking-engine", "expertise": "high"}
print(subsystem["expertise"])

# 실험 문화 예시: Python 3에서 실행 가능한 코드
experiment = {"hypothesis": "faster signup", "metric": "conversion"}
print(experiment["metric"])

# 포스트모템 문화 예시: Python 3에서 실행 가능한 코드
postmortem = {"action_items": 3, "blame": False}
print(not postmortem["blame"])

# 심리적 안전 예시: Python 3에서 실행 가능한 코드
team = {"can_report_risk": True}
print(team["can_report_risk"])

# 생산성 측정(DORA) 예시: Python 3에서 실행 가능한 코드
dora = {"lead_time_hours": 4, "restore_minutes": 30}
print(dora["lead_time_hours"] < 24)

# 기술 비전 수립 예시: Python 3에서 실행 가능한 코드
vision = {"target": "modular platform", "years": 3}
print(vision["target"])

# 프로토타입 vs 프로덕션 예시: Python 3에서 실행 가능한 코드
prototype = {"monitoring": False}
production = {"monitoring": True}
print(production["monitoring"])

# 프루프 오브 컨셉(POC) 예시: Python 3에서 실행 가능한 코드
poc = {"goal": "verify latency", "passed": True}
print(poc["passed"])

# 기술 스파이크 예시: Python 3에서 실행 가능한 코드
spike = {"question": "can use grpc?", "days": 2}
print(spike["days"])

# 리플랫폼 전략 예시: Python 3에서 실행 가능한 코드
app = {"code_change": "small", "platform": "kubernetes"}
print(app["platform"])

# 기술 엑시트 전략 예시: Python 3에서 실행 가능한 코드
exit_plan = {"data_export": True, "adapter": True}
print(all(exit_plan.values()))

# 일몰(Sunset) 계획 예시: Python 3에서 실행 가능한 코드
sunset = {"notice_days": 90, "replacement": True}
print(sunset["notice_days"])

# 지식 이전 예시: Python 3에서 실행 가능한 코드
owners = {"old": "Kim", "new": "Lee"}
print(owners["new"])

# 레버리지 포인트 예시: Python 3에서 실행 가능한 코드
impact = {"button_color": 1, "build_time": 8}
print(max(impact, key=impact.get))

# RFC 프로세스(기술 문서) 예시: Python 3에서 실행 가능한 코드
rfc = {"status": "review", "comments": 5}
print(rfc["status"])

# 기술 레이더 예시: Python 3에서 실행 가능한 코드
radar = {"Kubernetes": "adopt", "OldLib": "hold"}
print(radar["Kubernetes"])

# 기술 표준화 예시: Python 3에서 실행 가능한 코드
standards = {"logging": "json", "runtime": "container"}
print(standards["logging"])

# 이너소스(InnerSource) 예시: Python 3에서 실행 가능한 코드
repo = {"open_to_org": True, "requires_review": True}
print(all(repo.values()))

# 기여 모델(Contribution Model) 예시: Python 3에서 실행 가능한 코드
model = {"fork": True, "reviewers": 2}
print(model["reviewers"])

# 코드 소유권(Code Ownership) 예시: Python 3에서 실행 가능한 코드
owners = {"payments/": "fintech-team"}
print(owners["payments/"])

# CODEOWNERS 파일 예시: Python 3에서 실행 가능한 코드
codeowners = {"*.py": "@backend", "infra/": "@platform"}
print(codeowners["infra/"])

# 알람 표준화 예시: Python 3에서 실행 가능한 코드
alert = {"severity": "page", "runbook": True}
print(alert["severity"])

# 온콜(On-call) 문화 예시: Python 3에서 실행 가능한 코드
oncall = {"primary": "Lee", "backup": "Kim"}
print(oncall["backup"])
